851	func normalizeHistorySearchText(value string) string {
852		var b strings.Builder
853		runes := []rune(value)
854		lastSpace := true
855		for i, r := range runes {
856			if unicode.IsLetter(r) || unicode.IsDigit(r) {
857				if !lastSpace && historyCamelBoundary(runes, i) {
858					b.WriteByte(' ')
859				}
860				b.WriteRune(unicode.ToLower(r))
861				lastSpace = false
862				continue
863			}
864			if !lastSpace {
865				b.WriteByte(' ')
866				lastSpace = true
867			}
868		}
869		return strings.TrimSpace(b.String())
870	}
871	
872	func historyCamelBoundary(runes []rune, index int) bool {
873		if index <= 0 || index >= len(runes) {
874			return false
875		}
876		current := runes[index]
877		previous := runes[index-1]
878		if !unicode.IsLetter(current) || !(unicode.IsLetter(previous) || unicode.IsDigit(previous)) || !unicode.IsUpper(current) {
879			return false
880		}
881		if unicode.IsLower(previous) || unicode.IsDigit(previous) {
882			return true
883		}
884		if unicode.IsUpper(previous) && index+1 < len(runes) && unicode.IsLower(runes[index+1]) {
885			return true
886		}
887		return false
888	}
