890	func historyTextMatchesQuery(text, query string) bool {
891		query = strings.ToLower(strings.TrimSpace(query))
892		if query == "" {
893			return false
894		}
895		text = strings.ToLower(text)
896		if strings.Contains(text, query) {
897			return true
898		}
899		normalizedText := normalizeHistorySearchText(text)
900		normalizedQuery := normalizeHistorySearchText(query)
901		if normalizedQuery == "" {
902			return false
903		}
904		if strings.Contains(normalizedText, normalizedQuery) {
905			return true
906		}
907		return false
908	}
909	
910	func historyRecordMatchesQuery(record historyRecord, query string) bool {
911		return historyTextMatchesQuery(record.Summary+" "+strings.Join(record.Terms, " ")+" "+record.Path, query)
912	}
913	
914	// historyRecordTimestamp recovers the session capture time encoded in the
915	// exported transcript path (sessions/<branch>/YYYYMMDDThhmmssZ_...jsonl) so
916	// callers can order records by recency and report when a record was produced.
917	// Records sourced from non-session paths (seed/manifest) have no timestamp.
918	func historyRecordTimestamp(path string) (time.Time, bool) {
919		base := filepath.Base(filepath.FromSlash(path))
920		if len(base) < 16 {
921			return time.Time{}, false
922		}
923		stamp := base[:16]
924		parsed, err := time.Parse("20060102T150405Z", stamp)
925		if err != nil {
926			return time.Time{}, false
927		}
928		return parsed.UTC(), true
929	}
930	
931	// historyRecordMatchedTerms reports which query tokens and identifiers actually
932	// appear in a record. Returning these makes a match explainable to an agent and
933	// turns a zero/low-signal result into an actionable "these terms hit, these did
934	// not" diagnostic instead of an opaque miss.
935	func historyRecordMatchedTerms(record historyRecord, query string) []string {
936		recordText := normalizeHistorySearchText(record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path)
937		recordRaw := strings.ToUpper(record.Summary + " " + strings.Join(record.Terms, " ") + " " + record.Path)
938		seen := map[string]struct{}{}
939		var matched []string
940		for _, term := range historyQueryTerms(query) {
941			if strings.Contains(recordText, term) {
942				if _, ok := seen[term]; !ok {
943					seen[term] = struct{}{}
944					matched = append(matched, term)
945				}
946			}
947		}
948		for _, identifier := range historyIdentifierQueryTerms(query) {
949			if strings.Contains(recordRaw, identifier) {
950				key := strings.ToLower(identifier)
951				if _, ok := seen[key]; !ok {
952					seen[key] = struct{}{}
953					matched = append(matched, identifier)
954				}
955			}
956		}
957		return matched
958	}
959	
960	func rankHistoryRecords(index historyIndex, kind, query string, limit int) []historyRecord {
961		scored := rankHistoryRecordsScored(index, kind, query, limit, 0)
962		records := make([]historyRecord, 0, len(scored))
963		for _, item := range scored {
964			records = append(records, item.Record)
965		}
966		return records
967	}
968	
969	// rankHistoryRecordsScored ranks records and returns the scores so callers can
970	// surface why a record matched. minMatches relaxes the term-coverage threshold
971	// (0 = strict default, 1 = best-effort partial matching).
972	func rankHistoryRecordsScored(index historyIndex, kind, query string, limit, minMatches int) []scoredHistoryRecord {
973		if limit <= 0 {
974			return nil
975		}
976		allowed := historyInspectKinds(kind)
977		scored := make([]scoredHistoryRecord, 0, min(len(index.Records), limit))
978		seen := map[string]struct{}{}
979		for i, record := range index.Records {
980			if len(allowed) > 0 {
981				if _, ok := allowed[record.Kind]; !ok {
982					continue
983				}
984			}
985			score := historyRecordQueryScoreMin(record, query, minMatches)
986			if score == 0 {
987				continue
988			}
989			score += historyInspectKindPreference(kind, record.Kind)
990			matchKey := normalizeHistorySearchText(record.Summary)
991			if _, ok := seen[matchKey]; ok {
992				continue
993			}
994			seen[matchKey] = struct{}{}
995			scored = append(scored, scoredHistoryRecord{Record: record, Score: score, Order: i})
996		}
