package cli

import (
	"bytes"
	"encoding/binary"
	"math"
	"os"
	"path/filepath"
)

// embedStore persists fact vectors under facts/<branch>/embeddings/ so an
// interactive recall/brief does not re-embed the whole branch on every CLI
// invocation (each process otherwise starts with a cold in-memory cache). The
// file is a regenerable derived artifact, like facts.ndjson itself.
//
// Keying is by content-derived fact id, and the header records the embedder's
// model id + dim: a model swap (or any dim change) fails the load and triggers
// a clean rebuild, so stale vectors from a different backend are never mixed in.
type embedStore struct {
	path    string // absolute path to vectors.bin
	modelID string
	dim     int
}

const (
	embedStoreFileName = "vectors.bin"
	embedStoreDirName  = "embeddings"
	embedStoreMagic    = "EBV1"
)

func newEmbedStore(brainDir, branch, modelID string, dim int) *embedStore {
	dir := filepath.Join(brainDir, filepath.FromSlash(factsBranchRelDir(branch)), embedStoreDirName)
	return &embedStore{path: filepath.Join(dir, embedStoreFileName), modelID: modelID, dim: dim}
}

// load reads persisted vectors, returning an empty map (not an error) whenever
// the cache is absent, unreadable, or built for a different model/dim — every
// such case is a cache miss that the caller refills by embedding. A cache is
// never load-bearing, so corruption degrades to a rebuild rather than failing.
func (s *embedStore) load() map[string][]float32 {
	out := map[string][]float32{}
	raw, err := os.ReadFile(s.path)
	if err != nil {
		return out
	}
	r := &byteReader{b: raw}
	if string(r.take(4)) != embedStoreMagic {
		return out
	}
	modelID := string(r.take(int(r.u16())))
	dim := int(r.u32())
	count := int(r.u32())
	if r.err != nil || modelID != s.modelID || dim != s.dim || dim <= 0 {
		return out // model/dim mismatch -> full rebuild
	}
	for i := 0; i < count; i++ {
		id := string(r.take(int(r.u16())))
		vec := make([]float32, dim)
		for d := 0; d < dim; d++ {
			vec[d] = math.Float32frombits(r.u32())
		}
		if r.err != nil {
			return map[string][]float32{} // truncated/corrupt -> rebuild
		}
		out[id] = vec
	}
	return out
}

// save atomically writes the given vectors. The caller passes only the vectors
// for facts present this run, so removed/superseded facts are pruned on rewrite.
func (s *embedStore) save(vecs map[string][]float32) error {
	// Count the entries we will actually write (skipping any wrong-dim vector)
	// so the header count matches the body exactly — a mismatch would make the
	// next load() see a truncated file and force an unnecessary rebuild.
	count := 0
	for _, vec := range vecs {
		if len(vec) == s.dim {
			count++
		}
	}

	var buf bytes.Buffer
	buf.WriteString(embedStoreMagic)
	id := []byte(s.modelID)
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(id)))
	buf.Write(id)
	_ = binary.Write(&buf, binary.LittleEndian, uint32(s.dim))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(count))
	for factID, vec := range vecs {
		if len(vec) != s.dim {
			continue
		}
		_ = binary.Write(&buf, binary.LittleEndian, uint16(len(factID)))
		buf.WriteString(factID)
		for _, v := range vec {
			_ = binary.Write(&buf, binary.LittleEndian, math.Float32bits(v))
		}
	}
	if err := os.MkdirAll(filepath.Dir(s.path), 0o700); err != nil {
		return err
	}
	return writeFileAtomic(s.path, buf.Bytes(), 0o600)
}

package cli

import (
	"encoding/binary"
	"errors"
	"fmt"
	"math"
	"strings"
	"sync"
	"unicode"

	entirebrain "github.com/ashtom/entire-brain"
)

// Embedder turns text into a unit-length vector for semantic recall. It is the
// Phase D abstraction boundary: the bundled backend is a pure-Go Model2Vec
// static model (staticEmbedder), but a transformer bi-encoder (ONNX) or a
// provider-shelled embedder can drop in behind this interface without touching
// the ranking path, once the eval harness shows the static model leaves recall
// headroom. Embed returns a slice of length Dim(); input that tokenizes to
// nothing (empty/whitespace-only) returns the zero vector, which callers treat
// as "no signal". Unknown words map to [UNK] and so still yield a non-zero
// vector.
type Embedder interface {
	Embed(text string) []float32
	Dim() int
	// ID identifies the model + revision, used to invalidate cached fact
	// vectors when the backend changes.
	ID() string
}

// staticEmbedder is a Model2Vec static embedding table: tokenize (BERT
// WordPiece) -> gather per-token vectors -> mean-pool -> L2-normalize. The
// matrix is int8 per-column quantized; rows are dequantized on gather, which
// keeps only ~the int8 table resident and is cheap since each text touches only
// a handful of tokens.
type staticEmbedder struct {
	id      string
	dim     int
	vocab   map[string]int32
	matrix  []int8    // vocab*dim, row-major
	scales  []float32 // len dim, per-column dequant scale
	unkID   int32
	cont    string // WordPiece continuation prefix, e.g. "##"
	lower   bool
	strip   bool
	chinese bool
}

const embedModelMagic = "EBM1"

// maxWordPieceChars matches BERT's max_input_chars_per_word: a token longer
// than this is emitted as [UNK] rather than greedily decomposed.
const maxWordPieceChars = 100

func loadStaticEmbedder(raw []byte) (*staticEmbedder, error) {
	r := &byteReader{b: raw}
	if string(r.take(4)) != embedModelMagic {
		return nil, errors.New("embed model: bad magic")
	}

